def load_cases():
    result = {}
    for line in RAW.splitlines():
        if not line.strip():
            continue
        cells = line.split('|')
        if len(cells) != 10:
            raise ValueError(f'Expected 10 fields: {line[:80]} ({len(cells)})')
        key, actor, pre, inputs, steps, output, state, alt, error, fixture = cells
        if key in result:
            raise ValueError(f'Duplicate {key}')
        given, when, then = fixture.split(' / ')
        result[key] = dict(actor=actor, pre=pre, inputs=inputs, steps=steps.split('~'), output=output,
                           state=state, alt=alt, error=error, given=given, when=when, then=then)
    return result
